CREATE TABLE users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE auth_attempts (key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE factions (id TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE uploads (key TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL REFERENCES users(id),mime TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cards (id TEXT PRIMARY KEY,faction_id TEXT NOT NULL REFERENCES factions(id),owner_user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,rarity TEXT NOT NULL CHECK(rarity IN('legendary','hero','rare','common')),hp INTEGER NOT NULL CHECK(typeof(hp)='integer' AND hp BETWEEN 10 AND 10000),attack INTEGER NOT NULL CHECK(typeof(attack)='integer' AND attack BETWEEN 1 AND 1000),passive_code TEXT,special_attack_code TEXT,image_key TEXT NOT NULL REFERENCES uploads(key),is_exodia INTEGER NOT NULL DEFAULT 0 CHECK(is_exodia IN(0,1)),review_status TEXT NOT NULL DEFAULT 'draft' CHECK(review_status IN('draft','pending','approved','rejected')),is_usable INTEGER NOT NULL DEFAULT 0 CHECK(is_usable IN(0,1) AND (is_usable=0 OR (review_status='approved' AND archived=0))),rejection_reason TEXT,archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX cards_faction ON cards(faction_id,archived);
CREATE INDEX cards_owner ON cards(owner_user_id,archived);
CREATE INDEX cards_review ON cards(review_status,archived);
CREATE TRIGGER exodia_insert BEFORE INSERT ON cards WHEN NEW.is_exodia=1 AND NEW.archived=0 AND (SELECT count(*) FROM cards WHERE faction_id=NEW.faction_id AND is_exodia=1 AND archived=0)>=5 BEGIN SELECT RAISE(ABORT,'exodia_limit'); END;
CREATE TRIGGER exodia_update BEFORE UPDATE ON cards WHEN NEW.is_exodia=1 AND NEW.archived=0 AND (SELECT count(*) FROM cards WHERE faction_id=NEW.faction_id AND is_exodia=1 AND archived=0 AND id!=NEW.id)>=5 BEGIN SELECT RAISE(ABORT,'exodia_limit'); END;
CREATE TABLE card_audit_logs (id TEXT PRIMARY KEY,card_id TEXT NOT NULL REFERENCES cards(id),actor_user_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,from_status TEXT,to_status TEXT,reason TEXT,card_version INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX audit_card ON card_audit_logs(card_id,card_version);
